using System.ComponentModel;
using ModelContextProtocol.Server;
using SimplePZMapmaker.Core;
using SimplePZMapmaker.Core.Export;
namespace SimplePZMapmaker.Web.Services;

[McpServerToolType]
public sealed class McpPlanningTools(AgentProjectStore maps,AgentWorldStore worlds,AgentPlanningStore plans,GameAssetCatalog assets,StaticModelCatalog models) {
 [McpServerTool(Name="building_template_read",ReadOnly=true,UseStructuredContent=true),Description("Get the complete authored building for a template ID from building_templates. It includes rooms, signed floors, stairs, resources and roof. Use world_building_put with absolute coordinates to place it in a shared world.")]
 public Building ReadTemplate(string templateId){var b=HousingTemplates.Create(templateId);AssetRules.Building(b,assets);return b;}
 [McpServerTool(Name="world_buildings",ReadOnly=true,UseStructuredContent=true),Description("List global and section-local building IDs in a world, with owning memberId and absolute tile coordinates. Pass memberId to world_building_read/replace for section-local buildings.")]
 public object WorldBuildings(string sessionToken){var w=worlds.Read(sessionToken).World;return new{global=w.Buildings.Select(b=>new{b.Id,b.Name,b.X,b.Y,b.Width,b.Height}),sections=w.Maps.Select(m=>new{memberId=m.Id,buildings=m.Project.Buildings.Select(b=>new{b.Id,b.Name,x=m.Project.WorldX*256+b.X,y=m.Project.WorldY*256+b.Y,b.Width,b.Height})})};}
 [McpServerTool(Name="world_building_read",ReadOnly=true,UseStructuredContent=true),Description("Read one complete building in absolute world coordinates. memberId null selects a global building; a section ID selects its local building. Original data is isolated and can be edited before world_building_replace.")]
 public Building ReadWorldBuilding(string sessionToken,string buildingId,string? memberId=null){var w=worlds.Read(sessionToken).World;if(memberId is null)return NeighborhoodPlanner.Copy(w.Buildings.SingleOrDefault(b=>b.Id==buildingId)??throw new ArgumentException("Общее здание не найдено."));var member=w.Maps.SingleOrDefault(m=>m.Id==memberId)??throw new ArgumentException("Участок не найден.");var building=NeighborhoodPlanner.Copy(member.Project.Buildings.SingleOrDefault(b=>b.Id==buildingId)??throw new ArgumentException("Здание участка не найдено."));building.X+=member.Project.WorldX*256;building.Y+=member.Project.WorldY*256;return building;}
 [McpServerTool(Name="world_building_replace",UseStructuredContent=true),Description("Replace an exact existing global or section-local building by a complete absolute-coordinate design against a revision. Replacing a local building promotes it to the shared layer, allowing annexes across section seams. Preserve the original building ID; invalid geometry or coverage leaves the whole world unchanged.")]
 public object ReplaceWorldBuilding(string sessionToken,long expectedRevision,string buildingId,Building building,string? memberId=null){if(building.Id!=buildingId)throw new ArgumentException("Сохраните идентификатор исходного здания.");AssetRules.Building(building,assets);ModelRules.Building(building,models);var s=worlds.Mutate(sessionToken,expectedRevision,w=>{if(memberId is null){var index=w.Buildings.FindIndex(b=>b.Id==buildingId);if(index<0)throw new ArgumentException("Исходное общее здание не найдено.");w.Buildings[index]=NeighborhoodPlanner.Copy(building);}else{var m=w.Maps.SingleOrDefault(m=>m.Id==memberId)??throw new ArgumentException("Участок не найден.");if(m.Project.Buildings.RemoveAll(b=>b.Id==buildingId)!=1)throw new ArgumentException("Исходное здание участка не найдено.");w.Buildings.Add(NeighborhoodPlanner.Copy(building));}ValidateWorld(w);});return new{s.Revision};}
 [McpServerTool(Name="neighborhood_plan_create",UseStructuredContent=true),Description("Plan a neighborhood in an isolated proposal with explicit region, count, maximum floors, spacing, allowed template IDs, seed and road constraints. Existing buildings, water and objects remain untouched. Returns proposalId and warnings; commit is separate.")]
 public object CreateMapPlan(string sessionToken,long expectedRevision,NeighborhoodConstraints constraints){var s=maps.Read(sessionToken);Check(s.Revision,expectedRevision);var plan=NeighborhoodPlanner.Create(s.Project,constraints);plan.BaseRevision=s.Revision;Stamp(plan);plans.Save(sessionToken,plan);return Brief(plan);}
 [McpServerTool(Name="neighborhood_plan_read",ReadOnly=true,UseStructuredContent=true),Description("Read an isolated proposal with exact buildings, roads and constraints. No editor mutation.")]
 public NeighborhoodPlan ReadPlan(string sessionToken,string proposalId)=>plans.Read(sessionToken,proposalId);
 [McpServerTool(Name="neighborhood_plan_commit",UseStructuredContent=true),Description("Apply a map neighborhood proposal atomically against its base revision. Browser receives it as one undoable action. Existing manual content stays intact.")]
 public object CommitMapPlan(string sessionToken,string proposalId,long expectedRevision){var plan=plans.Read(sessionToken,proposalId);Check(plan.BaseRevision,expectedRevision);var s=maps.Mutate(sessionToken,expectedRevision,p=>{NeighborhoodPlanner.Apply(p,plan);AssetRules.Project(p,assets);models.Validate(p);},"agent");return new{s.Revision,s.Author,proposalId};}
 [McpServerTool(Name="world_summary",ReadOnly=true,UseStructuredContent=true),Description("Read a browser-shared world session. Coordinates of global buildings are absolute tiles; section positions are native256-tile cells. Every mutation uses the current revision.")]
 public object WorldSummary(string sessionToken){var s=worlds.Read(sessionToken);return new{s.Revision,s.Author,s.Updated,s.World.Name,bounds=WorldAssembler.Validate(s.World),sections=s.World.Maps.Select(m=>new{m.Id,m.Project.Name,m.Project.WorldX,m.Project.WorldY,m.Project.Width,m.Project.Height,buildings=m.Project.Buildings.Count}),globalBuildings=s.World.Buildings.Select(b=>new{b.Id,b.Name,b.X,b.Y,b.Width,b.Height}),elevation=s.World.Elevation is not null};}
 [McpServerTool(Name="world_plan_create",UseStructuredContent=true),Description("Create an isolated whole-world neighborhood proposal across selected sections. Constraints use local section coordinates, with a single global building budget. Roads, water and existing/manual buildings are protected. Proposal commit is separate.")]
 public object CreateWorldPlan(string sessionToken,long expectedRevision,NeighborhoodConstraints constraints,string[]? memberIds=null){
  var s=worlds.Read(sessionToken);Check(s.Revision,expectedRevision);NeighborhoodPlanner.ValidateConstraints(constraints);var plan=new NeighborhoodPlan{BaseRevision=s.Revision,Constraints=NeighborhoodPlanner.Copy(constraints)};
  if(memberIds is {Length:>128}||memberIds is not null&&memberIds.Any(id=>!s.World.Maps.Any(m=>m.Id==id)))throw new ArgumentException("В задании указана неизвестная секция мира.");
  var selected=s.World.Maps.Where(m=>memberIds is null||memberIds.Contains(m.Id)).ToArray();var sectionIndex=0;
  foreach(var member in selected){
   var remaining=constraints.MaximumBuildings-plan.Buildings.Count;if(remaining==0)break;
   var c=NeighborhoodPlanner.Copy(constraints);c.MaximumBuildings=(int)Math.Ceiling(remaining/(double)(selected.Length-sectionIndex++));c.MinimumBuildings=0;c.Seed=unchecked(c.Seed+plan.Buildings.Count);c.Width=Math.Min(c.Width,member.Project.Width-c.X);c.Height=Math.Min(c.Height,member.Project.Height-c.Y);if(c.Width<16||c.Height<16)continue;
   var p=NeighborhoodPlanner.Copy(member.Project);
   // Only the isolated planning raster is marked; full shared building edge footprints stay protected.
   foreach(var b in s.World.Buildings)foreach(var point in WorldAssembler.BuildingCells(b)){var x=point.X-p.WorldX*256;var y=point.Y-p.WorldY*256;if(x>=0&&y>=0&&x<p.Width&&y<p.Height)p.Terrain[y*p.Width+x]=Terrain.Water;}
   var section=NeighborhoodPlanner.Create(p,c,member.Id);plan.Buildings.AddRange(section.Buildings);plan.Roads.AddRange(section.Roads);
  }
  if(plan.Buildings.Count<constraints.MinimumBuildings)throw new ArgumentException("Мир не вмещает минимальное число зданий с заданными ограничениями.");if(plan.Buildings.Count<constraints.MaximumBuildings)plan.Warnings.Add("Часть бюджета не размещена: существующие здания, вода или размер секций ограничивают место.");Stamp(plan);plans.Save(sessionToken,plan);return Brief(plan);
 }
 [McpServerTool(Name="world_plan_commit",UseStructuredContent=true),Description("Apply all buildings and roads of a world proposal in one revision-protected transaction. Stale or invalid proposals leave the entire world unchanged.")]
 public object CommitWorldPlan(string sessionToken,string proposalId,long expectedRevision){var plan=plans.Read(sessionToken,proposalId);Check(plan.BaseRevision,expectedRevision);var s=worlds.Mutate(sessionToken,expectedRevision,w=>{if(plan.Buildings.Concat(plan.Roads.Select(r=>new PlannedBuilding{MemberId=r.MemberId})).Any(e=>e.MemberId is null||!w.Maps.Any(m=>m.Id==e.MemberId)))throw new ArgumentException("Предложение относится к другой структуре мира.");foreach(var m in w.Maps)NeighborhoodPlanner.Apply(m.Project,plan,m.Id);ValidateWorld(w);});return new{s.Revision,s.Author,proposalId};}
 [McpServerTool(Name="world_section_move",UseStructuredContent=true),Description("Move a section in native-cell coordinates. Reject overlaps; preserve world validation and manual content. Use world_summary to obtain member IDs.")]
 public object MoveSection(string sessionToken,long expectedRevision,string memberId,int cellX,int cellY){var s=worlds.Mutate(sessionToken,expectedRevision,w=>{var moved=WorldAssembler.Move(w,memberId,cellX,cellY);w.Maps=moved.Maps;ValidateWorld(w);});return new{s.Revision};}
 [McpServerTool(Name="world_building_put",UseStructuredContent=true),Description("Add or replace one complete global building in absolute world-tile coordinates, including a building spanning section borders. Existing ID replaces that building; new IDs add. Source resources, room access and sparse coverage must validate.")]
 public object PutWorldBuilding(string sessionToken,long expectedRevision,Building building){AssetRules.Building(building,assets);ModelRules.Building(building,models);var s=worlds.Mutate(sessionToken,expectedRevision,w=>{var b=NeighborhoodPlanner.Copy(building);var i=w.Buildings.FindIndex(a=>a.Id==b.Id);if(i<0)w.Buildings.Add(b);else w.Buildings[i]=b;ValidateWorld(w);});return new{s.Revision};}
 [McpServerTool(Name="world_section_generate",UseStructuredContent=true),Description("Generate and add a section to a shared world at native256-tile cell coordinates, with explicit size, seed, town/blank kind and game surface theme. Reject overlaps and invalidated shared buildings atomically.")]
 public object GenerateSection(string sessionToken,long expectedRevision,int cellX,int cellY,int size=256,string name="Участок агента",string kind="blank",int seed=42,string surfaceTheme="legacy"){
  var p=MapGenerator.Generate(new(){Name=name,Size=size,Kind=kind,Seed=seed,SurfaceTheme=surfaceTheme});p.WorldX=cellX;p.WorldY=cellY;var member=new WorldMapMember{Project=p};var s=worlds.Mutate(sessionToken,expectedRevision,w=>{w.Maps.Add(member);ValidateWorld(w);});return new{s.Revision,memberId=member.Id};
 }
 [McpServerTool(Name="world_remove_object",Destructive=true,UseStructuredContent=true),Description("Remove a section or a shared building by exact ID. Revision protected; removal cannot orphan another shared building or leave a world without land spawns.")]
 public object RemoveWorldObject(string sessionToken,long expectedRevision,string id){var s=worlds.Mutate(sessionToken,expectedRevision,w=>{if(w.Maps.RemoveAll(m=>m.Id==id)+w.Buildings.RemoveAll(b=>b.Id==id)==0)throw new ArgumentException("Объект мира не найден.");ValidateWorld(w);});return new{s.Revision};}
 [McpServerTool(Name="world_paint_terrain",UseStructuredContent=true),Description("Paint a bounded rectangle at absolute world-tile coordinates across existing section seams. terrain0..6 follows project_summary conventions; terrain3 water cannot cover buildings, models, props or spawns. Sparse gaps reject the whole operation.")]
 public object PaintWorld(string sessionToken,long expectedRevision,int x,int y,int width,int height,int terrain){
  if(width is <1 or >128||height is <1 or >128||terrain is <0 or >6)throw new ArgumentException("Для одной операции разрешено128×128 клеток земли.");var s=worlds.Mutate(sessionToken,expectedRevision,w=>{
   var masks=w.Maps.ToDictionary(m=>m.Id,m=>TerrainEditMask.Decode(m.Project));
   for(var yy=y;yy<y+height;yy++)for(var xx=x;xx<x+width;xx++){var member=WorldAssembler.MemberAt(w,xx,yy)??throw new ArgumentException("Область проходит через отсутствующую секцию.");var p=member.Project;var index=(yy-p.WorldY*256)*p.Width+xx-p.WorldX*256;p.Terrain[index]=(Terrain)terrain;p.SurfaceTiles.Remove(index);masks[member.Id][index/8]|=(byte)(1<<(index%8));p.Version=6;}
   foreach(var member in w.Maps)member.Project.TerrainEdits=TerrainEditMask.Encode(masks[member.Id]);ValidateWorld(w);
  });return new{s.Revision};
 }
 [McpServerTool(Name="world_section_preview",ReadOnly=true,UseStructuredContent=true),Description("Preview native sprites for at most48x48 tiles of a section, including clipped shared buildings. level is a signed floor. Sprite pages come from the installed catalog.")]
 public object PreviewWorld(string sessionToken,string memberId,int x=0,int y=0,int? level=0,int cellX=0,int cellY=0){var s=worlds.Read(sessionToken);ValidateWorld(s.World);return NativeScene.WorldCell(s.World,memberId,x,y,level,cellX,cellY);}
 [McpServerTool(Name="world_export",ReadOnly=true,UseStructuredContent=true),Description("Validate and export the whole current world as one native Build42 mod. No automatic game installation. Returns a revision-bound browser download URL.")]
 public object ExportWorld(string sessionToken,long expectedRevision){var s=worlds.Read(sessionToken);Check(s.Revision,expectedRevision);ValidateWorld(s.World);return new{s.Revision,downloadUrl=$"/api/agent/world/export/{sessionToken}/{s.Revision}"};}
 public void ValidateWorld(WorldProject w){WorldAssembler.Validate(w);foreach(var m in w.Maps){AssetRules.Project(m.Project,assets);models.Validate(m.Project);}foreach(var b in w.Buildings){AssetRules.Building(b,assets);ModelRules.Building(b,models);}}
 void Stamp(NeighborhoodPlan plan){foreach(var entry in plan.Buildings){AssetRules.Building(entry.Building,assets);ModelRules.Building(entry.Building,models);}}
 static object Brief(NeighborhoodPlan p)=>new{proposalId=p.Id,p.BaseRevision,buildings=p.Buildings.Count,roads=p.Roads.Count,p.Constraints,p.Warnings};
 static void Check(long current,long expected){if(current!=expected)throw new AgentRevisionConflict(current);}
}
